# CP28 Step 7B reconstructed representative real-FCS T/NK-interface atlas.
rm(list=ls()); source(file.path(Sys.getenv("SDY2583_REPO_ROOT",unset="."),"R","shared","figure_framework.R")); rp_install_and_load(c("dplyr","readr","tibble","ggplot2","patchwork","stringr"),"flowCore"); source(file.path(sd_repo_root(),"R","panels","CP28","MANIFEST_RECONSTRUCTED.R")); a<-sd_analysis_dir("CP28"); r<-file.path(a,"11_RData"); out<-file.path(a,"05_flow_figures_flowjo_style_TALL_LAYOUT_WHITE_BG"); dir.create(out,recursive=TRUE,showWarnings=FALSE); load(file.path(r,"SDY2583_CP28_STEP1_inventory_RECONSTRUCTED.RData")); load(file.path(r,"SDY2583_CP28_STEP4_composite_scores_RECONSTRUCTED.RData")); reps<-rp_select_representative_subjects(scored_data,CP28_MANIFEST$integrated_score); readr::write_csv(reps,file.path(out,"SDY2583_CP28_representative_samples_RECONSTRUCTED.csv")); plots<-list()
for(i in seq_len(nrow(reps))){sid<-reps$subject_id[i]; group<-as.character(reps$disease_group[i]); path<-fcs_files[grepl(paste0("^",sid,"_CP28"),basename(fcs_files))][1]; obj<-rp_read_transform(path); map<-obj$marker_map; ex<-flowCore::exprs(obj$ff); ch<-c(DUMP=rp_find_channel(map,c("dump","viability"),"BV510-A"),CD3=rp_find_channel(map,c("^CD3$"),"BV605-A"),CD8=rp_find_channel(map,c("^CD8$"),"PerCP-Cy5-5-A"),CD45RA=rp_find_channel(map,c("CD45RA"),"PE-Cy5-A"),CD27=rp_find_channel(map,c("^CD27$"),"BB515-A"),CD56=rp_find_channel(map,c("^CD56$"),"PE-CF594-A"),CD161=rp_find_channel(map,c("CD161"),"PE-A"),VALPHA7=rp_find_channel(map,c("Valpha7"),"PE-Cy7-A"),VA24=rp_find_channel(map,c("Va24","V.?24.*J.?11"),"BV650-A")); dump<-rp_vec(ex,ch["DUMP"])<=1.5; cd3d<-dump&rp_vec(ex,ch["CD3"])>2; cd8<-cd3d&rp_vec(ex,ch["CD8"])>2; cd3neg<-dump&rp_vec(ex,ch["CD3"])<=2
plots[[length(plots)+1]]<-rp_flow_density_plot(ex,ch["CD3"],ch["DUMP"],2,1.5,paste(group,sid,"CD3/dump")); plots[[length(plots)+1]]<-rp_flow_density_plot(ex[dump,,drop=FALSE],ch["CD3"],ch["CD8"],2,2,paste(group,"CD3/CD8")); plots[[length(plots)+1]]<-rp_flow_density_plot(ex[cd8,,drop=FALSE],ch["CD45RA"],ch["CD27"],2,2,paste(group,"CD45RA/CD27")); plots[[length(plots)+1]]<-rp_flow_density_plot(ex[cd3d,,drop=FALSE],ch["VALPHA7"],ch["CD161"],1.5,1.5,paste(group,"Valpha7/CD161")); plots[[length(plots)+1]]<-rp_flow_density_plot(ex[cd3d,,drop=FALSE],ch["VA24"],ch["CD8"],1.5,2,paste(group,"Va24/CD8")); plots[[length(plots)+1]]<-rp_flow_density_plot(ex[cd3neg,,drop=FALSE],ch["CD56"],ch["CD8"],1.5,2,paste(group,"CD3neg CD56/CD8"))}
rp_save_flow_atlas(plots,file.path(out,"FigureS_CP28_representative_TNK_gating_RECONSTRUCTED.pdf"),ncol=2,width=9,height=24)
